		ColorWhite:       "#cdd6f4",
		ColorBlack:       "#1e1e2e",
		ColorBackground:  "#1e1e2e",
		TitleFg:          "#cba6f7",
		AppTitleFg:       "#cba6f7",
		SubTitleFg:       "#b4befe",
		ButtonFg:         "#1e1e2e",
		ButtonBg:         "#cba6f7",
		ButtonInactiveFg: "#cdd6f4",
		ButtonInactiveBg: "#585b70",
		TabActiveFg:      "#1e1e2e",
		TabActiveBg:      "#b4befe",
