// ThemeDir returns the themes directory (~/.devdesk/themes/)
func ThemeDir() (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(homeDir, ".devdesk", "themes"), nil
}

// LoadTheme loads a theme from a JSON file.
// If name is empty, "dark" or "default", returns the built-in default theme
func LoadTheme(name string) (*Theme, error) {
	if name == "" || name == "dark" || name == "default" {
		return DefaultTheme(), nil
	}

	dir, err := ThemeDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get theme directory: %w", err)
	}

	path := filepath.Join(dir, name+".json")
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read theme '%s': %w", name, err)
	}

	var t Theme
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("failed to parse theme '%s': %w", name, err)
	}

	if err := validateTheme(&t); err != nil {
		return nil, fmt.Errorf("invalid theme '%s': %w", name, err)
	}

	// Ensure the name is set
	if t.Name == "" {
		t.Name = name
	}

	return &t, nil
}

// ListThemes returns the list of available themes.
// Always includes "default" (built-in theme) + the JSON files in the themes directory
func ListThemes() ([]string, error) {
	themes := []string{"default"}

	dir, err := ThemeDir()
	if err != nil {
		return themes, nil // Return at least "dark"
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		return themes, nil // Directory doesn't exist yet
	}

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if themeName, ok := strings.CutSuffix(name, ".json"); ok {
			// Avoid duplicating the built-in theme
			if themeName == "default" {
				continue
			}
			themes = append(themes, themeName)
		}
	}

	return themes, nil
}

// hexColorPattern is the only colour form a theme file may hold.
var hexColorPattern = regexp.MustCompile(`^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$`)

// validateTheme treats every string field of Theme other than name as a colour
// (a new non-colour string field must be excluded here). It refuses a theme
// holding a non-empty colour that is not #rgb or #rrggbb, naming the first
// such key (in declaration order) and its value. An empty value is not an error:
// it selects the fallback applyColor documents.
func validateTheme(t *Theme) error {
	v := reflect.ValueOf(t).Elem()
	for i := 0; i < v.NumField(); i++ {
		key, _, _ := strings.Cut(v.Type().Field(i).Tag.Get("json"), ",")
		if key == "name" || v.Field(i).Kind() != reflect.String {
			continue
		}
		if val := v.Field(i).String(); val != "" && !hexColorPattern.MatchString(val) {
			return fmt.Errorf("%s: %q is not #rgb or #rrggbb", key, val)
		}
	}
	return nil
}

// applyColor returns a color.Color from a hex string, or the fallback if empty.
func applyColor(hex string, fallback color.Color) color.Color {
	if hex == "" {
		return fallback
	}
	return lipgloss.Color(hex)
}

// Hex formats c as "#rrggbb". Anything that is not a color.RGBA (NoColor, the
// empty Color, an ANSI index, nil) has no fixed value and gives "none".
func Hex(c color.Color) string {
	rgb, err := rgb8(c, "hex")
	if err != nil {
		return "none"
	}
	return fmt.Sprintf("#%02x%02x%02x", rgb[0], rgb[1], rgb[2])
}

// ApplyTheme applies a theme by updating the global color variables
// then refreshing all styles
func ApplyTheme(t *Theme) {
	// Update the global semantic colors
	ColorOK = lipgloss.Color(t.ColorOK)
	ColorError = lipgloss.Color(t.ColorError)
	ColorWarn = lipgloss.Color(t.ColorWarn)

	ColorPrimary = lipgloss.Color(t.ColorPrimary)
	ColorSecondary = lipgloss.Color(t.ColorSecondary)
	ColorBorder = lipgloss.Color(t.ColorBorder)
	ColorText = lipgloss.Color(t.ColorText)
	ColorDim = lipgloss.Color(t.ColorDim)
	ColorHighlight = lipgloss.Color(t.ColorHighlight)
	ColorWhite = lipgloss.Color(t.ColorWhite)
	ColorBlack = lipgloss.Color(t.ColorBlack)
	ColorBackground = applyColor(t.ColorBackground, ColorBackground)

	// Apply per-component colors (falling back to semantic colors)
	ColorTitleFg = applyColor(t.TitleFg, ColorPrimary)
	ColorAppTitleFg = applyColor(t.AppTitleFg, ColorPrimary)
	ColorSubTitleFg = applyColor(t.SubTitleFg, ColorSecondary)

	ColorButtonFg = applyColor(t.ButtonFg, ColorWhite)
	ColorButtonBg = applyColor(t.ButtonBg, ColorPrimary)
	ColorButtonInactiveFg = applyColor(t.ButtonInactiveFg, ColorWhite)
	ColorButtonInactiveBg = applyColor(t.ButtonInactiveBg, ColorDim)

	ColorTabActiveFg = applyColor(t.TabActiveFg, ColorBlack)
	ColorTabActiveBg = applyColor(t.TabActiveBg, ColorSecondary)
	ColorTabInactiveFg = applyColor(t.TabInactiveFg, ColorDim)
	ColorTabInactiveBg = applyColor(t.TabInactiveBg, ColorCmdLineBg)

	ColorTableHeaderFg = applyColor(t.TableHeaderFg, ColorSecondary)

package cmdsuggest

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	minContrast       = 4.5 // WCAG AA, normal text
	minBorderContrast = 3.0 // WCAG 1.4.11, graphical objects
)

// themeFiles discovers the shipped themes by glob, so a new file is covered
// without touching this test.
func themeFiles(t *testing.T) []string {
	t.Helper()
	files, err := filepath.Glob("../../../themes/*.json")
	if err != nil {
		t.Fatal(err)
	}
	if len(files) == 0 {
		t.Fatal("no theme found under themes/*.json")
	}
	return files
}

// loadThemes returns the default theme and every shipped theme, by name, with
// the names sorted.
func loadThemes(t *testing.T) (map[string]*theme.Theme, []string) {
	t.Helper()
	themes := map[string]*theme.Theme{"default": theme.DefaultTheme()}
	for _, f := range themeFiles(t) {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		var th theme.Theme
		if err := json.Unmarshal(data, &th); err != nil {
			t.Fatalf("%s: %v", f, err)
		}
		themes[strings.TrimSuffix(filepath.Base(f), ".json")] = &th
	}
	names := make([]string, 0, len(themes))
	for name := range themes {
		names = append(names, name)
	}
	sort.Strings(names)
	return themes, names
}

// checkPairs fails, naming theme, pair and both colors, for each pair below min.
func checkPairs(t *testing.T, themeName string, pairs []Pair, min float64) {
	t.Helper()
	for _, p := range pairs {
		ratio, err := theme.ContrastRatio(p.Fg, p.Bg)
		if err != nil {
			t.Errorf("theme %s: pair %q: %v", themeName, p.Name, err)
			continue
		}
		if ratio < min {
			t.Errorf("theme %s: pair %q: contrast %.2f:1 (fg %s on bg %s), want >= %.1f:1",
				themeName, p.Name, ratio, p.Fg, p.Bg, min)
		}
	}
}

// Global color state: no t.Parallel in this file.
func TestPaletteContrastOnEveryTheme(t *testing.T) {
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })
	themes, names := loadThemes(t)
	for _, name := range names {
		th := themes[name]
		t.Run(name, func(t *testing.T) {
			// Start from the default theme, as the app does, so a theme
			// missing a key does not inherit the previous theme's value.
			theme.ApplyTheme(theme.DefaultTheme())
			theme.ApplyTheme(th)
			checkPairs(t, name, Palette(), minContrast)
		})
	}
}

// The palette frame adds a title and an input line: both are text and are
// part of Palette(), so the 4.5:1 loop above covers them.
func TestPaletteListsTitleAndInputPairs(t *testing.T) {
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })
	theme.ApplyTheme(theme.DefaultTheme())
	for _, want := range []string{"title", "input"} {
		found := false
		for _, p := range Palette() {
			if strings.Contains(strings.ToLower(p.Name), want) {
				found = true
			}
		}
		if !found {
			t.Errorf("Palette() has no %s pair", want)
		}
	}
}

// Border and prompt glyph are non-text graphics: WCAG 1.4.11 asks for 3:1.
func TestPaletteBorderContrastOnEveryTheme(t *testing.T) {
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })
	themes, names := loadThemes(t)
	for _, name := range names {
		th := themes[name]
		t.Run(name, func(t *testing.T) {
			theme.ApplyTheme(theme.DefaultTheme())
			theme.ApplyTheme(th)
			pairs := BorderPalette()
			if len(pairs) == 0 {
				t.Fatalf("theme %s: BorderPalette() is empty", name)
			}
			for _, p := range pairs {
				if p.Fg != theme.ColorPaletteBorder {
					t.Errorf("theme %s: pair %q uses %s, want ColorPaletteBorder %s", name, p.Name, p.Fg, theme.ColorPaletteBorder)
				}
				if p.Bg != theme.ColorBackground {
					t.Errorf("theme %s: pair %q sits on %s, want ColorBackground %s", name, p.Name, p.Bg, theme.ColorBackground)
				}
			}
			checkPairs(t, name, pairs, minBorderContrast)
		})
	}
}

// ColorDim is a decoration tone, not a text tone: it is not required to reach
// 4.5:1 anywhere, so no text pair may use it.
func TestPaletteNeverUsesDimAsTextColor(t *testing.T) {
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })
	theme.ApplyTheme(theme.DefaultTheme())
	for _, p := range Palette() {
		if p.Fg == theme.ColorDim {
			t.Errorf("pair %q uses ColorDim (%s) as its text color", p.Name, p.Fg)
		}
	}
}
