			t.Errorf("FS.ReadFile(%q): %v (len %d)", f, err, len(data))
		}
	}
	if _, err := FS.ReadFile("github-light.json"); err != nil {
		t.Errorf("github-light.json must be embedded: %v", err)
	}
}
